#ifndef IDEVICE_TEST_FFI_H
#define IDEVICE_TEST_FFI_H
/* Minimal FFI test double. Production headers are generated by cbindgen. */
#include <stdint.h>
#include <stddef.h>
#include <sys/socket.h>
typedef struct sockaddr idevice_sockaddr;
typedef socklen_t idevice_socklen_t;
#define HANDLE(name) typedef struct name { int alive; } name
HANDLE(IdeviceHandle); HANDLE(IdeviceSocketHandle); HANDLE(IdevicePairingFile);
HANDLE(IdeviceProviderHandle); HANDLE(UsbmuxdAddrHandle); HANDLE(UsbmuxdDeviceHandle);
HANDLE(UsbmuxdConnectionHandle); HANDLE(HouseArrestClientHandle); HANDLE(AfcClientHandle);
HANDLE(AdapterHandle); HANDLE(RsdHandshakeHandle);
#undef HANDLE
typedef struct IdeviceFfiError { int32_t code; int32_t sub_code; const char *message; } IdeviceFfiError;
void idevice_free(IdeviceHandle*);
void idevice_provider_free(IdeviceProviderHandle*);
void idevice_usbmuxd_addr_free(UsbmuxdAddrHandle*);
void idevice_usbmuxd_device_free(UsbmuxdDeviceHandle*);
void idevice_usbmuxd_connection_free(UsbmuxdConnectionHandle*);
void house_arrest_client_free(HouseArrestClientHandle*);
void idevice_error_free(IdeviceFfiError*);
IdeviceFfiError *house_arrest_client_connect(IdeviceProviderHandle*, HouseArrestClientHandle**);
IdeviceFfiError *house_arrest_client_connect_rsd(AdapterHandle*, RsdHandshakeHandle*, HouseArrestClientHandle**);
IdeviceFfiError *house_arrest_client_new(IdeviceHandle*, HouseArrestClientHandle**);
IdeviceFfiError *house_arrest_vend_container(HouseArrestClientHandle*, const char*, AfcClientHandle**);
IdeviceFfiError *house_arrest_vend_documents(HouseArrestClientHandle*, const char*, AfcClientHandle**);
#endif
